<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Random Date Generator','description'=>'Generate random dates between two selected dates.','url'=>'https://smarttoolz.in/tools/date-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Random Date Generator</h1><p>Generate random dates in a range.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Start<input id="a" type="date"></label><label>End<input id="b" type="date"></label><button id="go" class="tool-btn">Generate</button><p id="o"></p></div></section></main><script>let d=new Date();a.value=d.toISOString().slice(0,10);b.value=new Date(d.getFullYear(),11,31).toISOString().slice(0,10);go.onclick=()=>{let x=new Date(a.value+'T00:00'),y=new Date(b.value+'T23:59:59');o.textContent=x<=y?new Date(x.getTime()+Math.random()*(y-x)).toISOString().slice(0,10):'Invalid range.'};go.click()</script><?php smarttoolz_tool_page_end(); ?>